solution.solution.js:
function readBmpHeader(buffer) {
  if (buffer.byteLength < 54) throw new Error("too short for a BMP header");
  const view = new DataView(buffer);
  if (view.getUint8(0) !== 0x42 || view.getUint8(1) !== 0x4d) throw new Error("not a BMP file");
  if (view.getUint32(14, true) < 40) throw new Error("unsupported header");
  if (view.getUint16(26, true) !== 1) throw new Error("planes must be 1");
  const bitsPerPixel = view.getUint16(28, true);
  if (![1, 4, 8, 16, 24, 32].includes(bitsPerPixel)) throw new Error("bad bits per pixel");
  const width = view.getInt32(18, true);
  if (width <= 0) throw new Error("bad width");
  const rawHeight = view.getInt32(22, true);
  return {
    fileSize: view.getUint32(2, true),
    dataOffset: view.getUint32(10, true),
    width,
    height: Math.abs(rawHeight),
    topDown: rawHeight < 0,
    bitsPerPixel,
  };
}

unitTests:
function makeHeader({ width = 4, height = 2, bits = 24, planes = 1, size = 40, magic = "BM" } = {}) {
  const buf = new ArrayBuffer(54);
  const v = new DataView(buf);
  v.setUint8(0, magic.charCodeAt(0));
  v.setUint8(1, magic.charCodeAt(1));
  v.setUint32(2, 54 + 32, true);
  v.setUint32(10, 54, true);
  v.setUint32(14, size, true);
  v.setInt32(18, width, true);
  v.setInt32(22, height, true);
  v.setUint16(26, planes, true);
  v.setUint16(28, bits, true);
  return buf;
}

test("reads the fields", () => {
  checkEq(readBmpHeader(makeHeader()), { fileSize: 86, dataOffset: 54, width: 4, height: 2, topDown: false, bitsPerPixel: 24 });
});

test("negative height means top-down", () => {
  const h = readBmpHeader(makeHeader({ height: -3 }));
  checkEq([h.height, h.topDown], [3, true]);
});

test("refuses broken headers", () => {
  checkThrows(() => readBmpHeader(new ArrayBuffer(20)));
  checkThrows(() => readBmpHeader(makeHeader({ magic: "PN" })));
  checkThrows(() => readBmpHeader(makeHeader({ bits: 7 })));
  checkThrows(() => readBmpHeader(makeHeader({ planes: 2 })));
  checkThrows(() => readBmpHeader(makeHeader({ size: 12 })));
  checkThrows(() => readBmpHeader(makeHeader({ width: 0 })));
});

